def sha256(content: bytes) -> str:
    return hashlib.sha256(content).hexdigest()


def resolve_paths():
    cwd = Path.cwd().resolve()
    if cwd.name != BE:
        raise RuntimeError(f"REJECT: run from {BE}, current working directory: {cwd}")
    root = cwd.parent
    frontend = root / FE
    if not frontend.is_dir():
        raise RuntimeError(f"REJECT: sibling frontend {frontend} not found")
    if Path(__file__).resolve().parent != frontend.resolve():
        raise RuntimeError(f"REJECT: updater must reside in frontend root: {frontend}")
    return frontend


def payload_files():
    obj = json.loads(zlib.decompress(base64.b85decode(PAYLOAD_B85)).decode('utf-8'))
    if set(obj) != set(ORIGINAL):
        raise RuntimeError('REJECT: payload does not contain the expected file set')
    result = {k: v.encode('utf-8') for k,v in obj.items()}
    for path, binary in result.items():
        if sha256(binary) != UPDATED[path]:
            raise RuntimeError(f'REJECT: updater payload checksum mismatch: {path}')
    return result


def examine(frontend):
    states = {}
    for rel, expected in ORIGINAL.items():
        path = frontend / rel
        if not path.is_file():
            states[rel] = ('MISSING', None)
            continue
        h = sha256(path.read_bytes())
        state = 'ALREADY_APPLIED' if h == UPDATED[rel] else ('PATCH_NEEDED' if h == expected else 'UNEXPECTED')
        states[rel] = (state, h)
    return states


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    action=parser.add_mutually_exclusive_group(required=True)
    action.add_argument('--scan',action='store_true')
    action.add_argument('--apply',action='store_true')
    action.add_argument('--verify',action='store_true')
    args=parser.parse_args()
    try:
        frontend=resolve_paths()
        patch_files=payload_files()
        states=examine(frontend)
        print('[IPTH MES CONFIGFIX] 1.0.0 | BE_CWD', Path.cwd(), '| FE',frontend)
        for path,(state,digest) in states.items():
            print(f'[{state}] {path} | SHA256 {digest or "missing"}')
        counts={s for s,_ in states.values()}
        if args.scan:
            if any(s in {'MISSING','UNEXPECTED'} for s in counts):
                print('REJECT: source changed; supply a fresh collector snapshot.'); return 3
            print('SCAN PASS: no writes.'); return 0
        if args.verify:
            if counts != {'ALREADY_APPLIED'}:
                print('VERIFY FAIL: patch not applied to all 3 files.'); return 4
            st=(frontend/'src/store/ModelConfigStore.js').read_text(encoding='utf-8')
            if st.count('  lazyLoadHalb: async') != 1 or 'restoreSavedExtendedBOM' not in st:
                print('VERIFY FAIL: required JS markers missing.'); return 5
            print('VERIFY PASS: all expected SHA256 hashes match and behavior markers present.'); return 0
        if counts == {'ALREADY_APPLIED'}:
            print('APPLY: already applied; no changes.'); return 0
        if counts != {'PATCH_NEEDED'}:
            print('REJECT: requires all three files to match original collected snapshot. No writes.'); return 6
        stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
        backup=frontend/f'.ipth_assy_configfix_backup_{stamp}'
        if backup.exists():
            print('REJECT: backup directory already exists.'); return 7
        backup.mkdir(parents=True)
        # Save every original before modifying a single source file.
        for rel in ORIGINAL:
            b=backup/rel;b.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(frontend/rel,b)
            if sha256(b.read_bytes()) != ORIGINAL[rel]:
                raise RuntimeError('REJECT: backup checksum differs: '+rel)
        replaced=[]
        try:
            for rel,content in patch_files.items():
                dest=frontend/rel
                fd,tmp=tempfile.mkstemp(prefix='.'+dest.name+'.configfix.',dir=str(dest.parent))
                try:
                    os.chmod(tmp,dest.stat().st_mode & 0o777)
                    with os.fdopen(fd,'wb') as out:
                        out.write(content);out.flush();os.fsync(out.fileno())
                    os.replace(tmp,dest)
                    replaced.append(rel)
                finally:
                    if os.path.exists(tmp): os.unlink(tmp)
            if {state for state,_ in examine(frontend).values()} != {'ALREADY_APPLIED'}:
                raise RuntimeError('Post-apply checksum validation failed')
        except Exception:
            for rel in replaced:
                shutil.copy2(backup/rel,frontend/rel)
            raise
        print('[APPLY PASS] FE files updated. Backup:',backup)
        print('Next: python ../Interplex_MES_FE/IPTH_MES_AssyPacking_ConfigFix_v1.py --verify')
        print('Then rebuild/restart FRONTEND. No backend or database modification was performed.')
        return 0
    except Exception as error:
        print('[ERROR]',error, file=sys.stderr)
        return 2


if __name__ == '__main__':
    sys.exit(main())
